        'from torch import nn\nmodel=nn.Sequential(nn.Linear(4,16),nn.GELU(),nn.Linear(16,3)); opt=torch.optim.AdamW(model.parameters(),lr=1e-3)\na=torch.randn(8,4); target=torch.randint(0,3,(8,)); opt.zero_grad(set_to_none=True); loss=nn.functional.cross_entropy(model(a),target); loss.backward(); print(nn.utils.clip_grad_norm_(model.parameters(),1.0)); opt.step()',
