    dense("03_huggingface/25_prompting_context_chat_templates.ipynb", "Prompting, Context Engineering, and Chat Templates", ["Design prompts as versioned probabilistic interfaces", "Render and test Hugging Face chat templates", "Evaluate few-shot examples, context budgets, and injection boundaries"], [
        ("25.1 Prompting is interface design", "A prompt conditions a trained distribution; it does not install a rule or permission boundary. State the task, audience, supplied data, constraints, uncertainty behavior, and output contract. Use delimiters to distinguish instructions from untrusted data, but assume the model may still follow injected text. Positive instructions often work better than lists of prohibitions. Establish a zero-shot baseline before decomposition or few-shot examples, and measure success on frozen cases rather than optimizing one anecdote."),
        ("25.2 Few-shot and context engineering", "Examples teach local patterns without changing weights, but selection, order, label balance, similarity, and length affect behavior. Keep examples free of evaluation leakage and retrieve them by task-relevant similarity only under authorization. Context engineering chooses all messages, evidence, tool schemas, memory, and prior results under a token budget. Preserve authoritative constraints and unresolved commitments; summarize low-priority history with provenance. More context can distract, increase latency, and expose injection."),
        ("25.3 Chat templates are model artifacts", "Instruct checkpoints are trained on exact control tokens and role serialization. `apply_chat_template(tokenize=True)` is safest because rendering then ordinary tokenization can duplicate special tokens. Understand `add_generation_prompt` and continuing a final message, EOS boundaries, assistant masks, tool arguments, and reasoning controls. Templates are Jinja stored with tokenizer artifacts; whitespace changes can matter. Multimodal templates belong to processors and emit media placeholders. Pin, inspect, and regression-test rendered IDs across training and every serving engine."),
        ("25.4 Prompt evaluation and escalation", "Version prompt source, variables, rendered text hash, template/model/tokenizer revisions, and decoding. Evaluate correctness, constraint adherence, schema validity, abstention, robustness to irrelevant changes, injection, token cost, and latency. Use paired comparisons and slice results. When prompt complexity grows, decide whether constrained decoding, retrieval, tools, SFT, or deterministic code owns the requirement. Prompts cannot guarantee authorization, factuality, confidentiality, or exact computation; application controls remain authoritative."),
    ], [
        'cases=[{"input":"refund policy","expected_fields":{"answer","sources"}},{"input":"unknown policy","must_abstain":True}]\nprint(cases)',
        'examples=[("positive","Return one JSON object with answer and sources."),("negative","Do not ramble or omit JSON or add markdown.")]\nprint(*examples,sep="\\n")',
        'try:\n from transformers import AutoTokenizer\n tok=AutoTokenizer.from_pretrained("Qwen/Qwen2.5-0.5B-Instruct",local_files_only=True); messages=[{"role":"user","content":"Define perplexity."}]; ids=tok.apply_chat_template(messages,tokenize=True,add_generation_prompt=True); print(tok.decode(ids),len(ids))\nexcept Exception as e: print("Load/cache the public tokenizer to inspect its exact template:",type(e).__name__)',
        'results=[{"prompt":"v1","valid":8,"correct":6,"tokens":900},{"prompt":"v2","valid":10,"correct":7,"tokens":1300}]\nfor r in results: print(r["prompt"],"accuracy",r["correct"]/10,"tokens/correct",r["tokens"]/r["correct"])'
    ], ["Compare zero-shot and few-shot prompts on a frozen set.", "Write and test a minimal Jinja chat template.", "Build a token-budgeted context assembler."])

    dense("03_huggingface/26_hf_inference_model_selection.ipynb", "Hugging Face Inference APIs and Open-Model Selection", ["Move from pipeline to forward passes and hosted endpoints", "Select models using measured compatibility and constraints", "Control device maps, dtypes, batching, trust, and revisions"], [
        ("26.1 Select an artifact, not a leaderboard row", "Define task, languages, modalities, latency, throughput, memory, context, license, privacy, tool/structure needs, and hardware before choosing a model. Distinguish base, instruct, reasoning, dense, and MoE variants; total and active parameters differ. Inspect model and dataset cards, configuration, tokenizer, chat template, architecture support, quantized derivatives, and immutable revisions. Leaderboards suggest candidates but may use different prompts, templates, contamination, and hardware. Run a task-specific baseline and record exclusions."),
        ("26.2 Abstraction ladder", "`pipeline` provides task preprocessing and postprocessing for fast baselines. Auto tokenizer/processor plus AutoModel exposes batching and generation. Direct forward passes expose logits, loss, hidden states, and cache behavior. `InferenceClient` targets remote providers; dedicated endpoints and local servers change operational ownership. Choose the highest abstraction that exposes required controls, then inspect what it adds. Do not mix pipeline-returned full text with newly generated tokens or assume model-specific output schemas are uniform."),
        ("26.3 Loading and memory", "Pin model and tokenizer commits together. Review `trust_remote_code` and custom repositories before execution. Choose dtype supported by hardware, use device maps deliberately, and understand offload latency. `low_cpu_mem_usage`, Safetensors, sharded checkpoints, quantization, and attention implementations affect load and residency. Set pad token and padding side based on task. Measure peak memory after warmup, not just weight size; KV cache and workspaces grow with live tokens."),
        ("26.4 Compatibility and deployment", "Test chat rendering, greedy and sampled generation, stopping, streaming, structured output, tools, logprobs, batching, cancellation, and error behavior on the exact backend. A model loading in Transformers does not guarantee optimized vLLM or SGLang support. Keep a narrow internal request contract and engine conformance tests. Compare local inference, Hugging Face providers, managed endpoints, Ollama, and vLLM by data boundary, cold start, concurrency, cost, and operations. Store raw predictions and release a model-selection decision record."),
    ], [
        'requirements={"license":"commercial-compatible","memory_gib":16,"tools":True,"min_context":8192}; candidates=[{"id":"a","memory_gib":8,"tools":True,"context":32768},{"id":"b","memory_gib":20,"tools":True,"context":65536}]\nprint([c for c in candidates if c["memory_gib"]<=requirements["memory_gib"] and c["tools"] and c["context"]>=requirements["min_context"]])',
        'try:\n from transformers import pipeline\n print("pipeline is the baseline API; guarded to avoid an implicit model download")\nexcept ImportError: print("run setup")',
        'import torch\nfor dtype in [torch.float32,torch.float16,torch.bfloat16]: print(dtype,torch.finfo(dtype).bits)',
        'contract={"chat":True,"stream":True,"tools":True,"json_schema":True,"cancel":True}; observed={"chat":True,"stream":True,"tools":False,"json_schema":True,"cancel":False}\nprint("gaps",[k for k,v in contract.items() if v and not observed.get(k)])'
    ], ["Build a model-selection scorecard.", "Compare pipeline and direct generate outputs.", "Write a backend conformance suite."])

    dense("04_retrieval/29_embedding_reranker_training.ipynb", "Training Embedding Models and Rerankers", ["Derive contrastive bi-encoder and cross-encoder objectives", "Mine hard negatives without poisoning labels", "Fine-tune and evaluate retrieval by slice"], [
        ("29.1 Representation objectives", "Bi-encoders embed query and document independently for scalable retrieval. Contrastive training raises positive similarity relative to negatives; multiple-negatives ranking uses other positives in the batch as negatives and is efficient only when false negatives are controlled. Triplet and margin losses encode relative constraints. Normalize vectors when cosine similarity is intended. Dataset pairs define relevance and can teach shortcuts from source, length, or formatting."),
        ("29.2 Negatives and mining", "Random negatives are often too easy; lexical or dense mining finds confusable candidates that teach decision boundaries. A highly ranked unlabeled document may actually be relevant, creating false-negative gradients. Use human judgments, cross-encoder filtering, known-positive sets, and iterative audits. Mine with a frozen prior model and keep evaluation documents isolated. Balance domains and query frequencies by effective pairs or tokens."),
        ("29.3 Cross-encoder rerankers", "A cross-encoder jointly reads query and candidate and predicts relevance, capturing token interactions at greater latency. Train with pointwise classification, pairwise preference, or listwise ranking objectives. Calibrate scores only for the deployment candidate distribution. Reranker training cannot recover documents absent from first-stage candidates, so freeze candidate pools when evaluating reranker improvements and measure end-to-end recall separately."),
        ("29.4 Training and evaluation", "Sentence Transformers provides losses, trainers, evaluators, and Hub-compatible artifacts. Begin with a small domain dataset and guarded run; record base revision, pooling, maximum length, prompts, batch composition, negatives, and precision. Evaluate Recall@k, MRR, nDCG, MAP, latency, index size, multilingual/domain slices, and robustness to identifiers. Compare base and tuned models on a frozen corpus, rebuild the index after any embedding change, and retain rollback lineage."),
    ], [
        'import torch\nq=torch.nn.functional.normalize(torch.randn(4,8),dim=-1); d=torch.nn.functional.normalize(torch.randn(4,8),dim=-1); logits=q@d.T/.07; labels=torch.arange(4); print(torch.nn.functional.cross_entropy(logits,labels))',
        'pool=[{"id":"d1","score":.91,"known_positive":True},{"id":"d2","score":.89,"known_positive":False},{"id":"d3","score":.2,"known_positive":False}]\nprint("audit hard negatives",[x for x in pool if not x["known_positive"] and x["score"]>.5])',
        'pointwise=torch.tensor([2.,-1.]); labels=torch.tensor([1.,0.]); print(torch.nn.functional.binary_cross_entropy_with_logits(pointwise,labels))',
        'ranking=["d3","d1","d7"]; relevant={"d1","d2"}; print("recall@3",len(set(ranking)&relevant)/len(relevant),"RR",1/2)'
    ], ["Mine and audit hard negatives.", "Compare contrastive temperatures.", "Fine-tune a small embedding model and rebuild its index."])

    dense("06_evaluation_security/40_lighteval_benchmarking.ipynb", "Reproducible LLM Benchmarking with LightEval", ["Distinguish likelihood, generation, and judge tasks", "Define reproducible benchmark configurations", "Interpret aggregate scores, contamination, and uncertainty"], [
        ("40.1 A harness standardizes mechanics", "A benchmark harness makes prompts, few-shot selection, batching, metrics, model adapters, and result serialization repeatable. It does not make a benchmark representative or uncontaminated. LightEval is the actively maintained Hugging Face-aligned option for LLM evaluation. Pin its version, task revision, model/tokenizer/template, generation configuration, and backend. Run a small smoke subset before expensive evaluation and preserve per-example outputs."),
        ("40.2 Task types", "Log-likelihood tasks compare candidate continuation probabilities and require correct token boundaries and normalization. Generative tasks decode an answer and apply exact, normalized, executable, semantic, or judge graders. Few-shot examples alter context and must be fixed by seed and selection policy. Chat templates can change results materially. Stop sequences, maximum tokens, sampling, and answer extraction are part of the benchmark definition, not incidental CLI flags."),
        ("40.3 Statistics and contamination", "Aggregate accuracy conceals slices and item dependence. Report counts, paired differences, bootstrap intervals where appropriate, and failures. Pass@k depends on number and sampling distribution. Benchmark data may appear in pretraining or synthetic instruction corpora; use contamination checks, private or newly created tests, temporal splits, and perturbations. Leaderboard comparisons are invalid when prompts, few-shot counts, revisions, or inference settings differ."),
        ("40.4 Operational workflow", "Create a manifest, inspect rendered prompts, run deterministic baselines, execute the candidate and parent under identical settings, validate completion and error counts, then publish raw predictions plus summary. Distributed evaluation must avoid duplicate items and aggregate numerators/denominators correctly. Quality changes after quantization or serving-engine migration require the same frozen suite. Standard benchmarks complement product-specific tasks, safety tests, RAG and agent trajectories; none replaces them."),
    ], [
        'config={"harness":"lighteval@pinned","tasks":["task@revision"],"fewshot":0,"seed":42,"model":"org/model@commit","template":"tokenizer@commit"}; print(config)',
        'items=[{"type":"likelihood","scores":[-.2,-1.4],"gold":0},{"type":"generation","output":"42","reference":"42"}]; print(items)',
        'import random\ndiffs=[1,0,-1,1,1,0]; rng=random.Random(42); means=[sum(rng.choices(diffs,k=len(diffs)))/len(diffs) for _ in range(1000)]; print(sorted(means)[25],sorted(means)[975])',
        'results={"completed":98,"errors":2,"expected":100}; assert results["completed"]+results["errors"]==results["expected"]; print(results)'
    ], ["Define a custom task.", "Compare two checkpoints with paired intervals.", "Audit template and contamination sensitivity."])

    dense("09_capstones/49_capstone_build_language_model.ipynb", "Capstone I: Build, Pretrain, and Instruction-Tune a Language Model", ["Integrate tokenizer, decoder, pretraining, SFT, evaluation, and artifacts", "Use explicit gates between stages", "Produce a reproducible model card and release bundle"], [
        ("49.1 Product and experiment contract", "Define a deliberately narrow model: target corpus, supported language/domain, context length, vocabulary, parameter and token budget, hardware, success metrics, and excluded uses. Establish byte or n-gram baselines and a held-out split before training. This capstone reuses implementations from prerequisites through SFT rather than hiding them in one trainer. One-epoch course runs demonstrate integration, not a useful general assistant. Create a run directory containing immutable configuration and hashes, never credentials."),
        ("49.2 Tokenizer and pretraining gate", "Train a tokenizer only on training text, test round trips and fertility, then initialize a compatible decoder from configuration. Verify causal shift, masks, parameter tying, one-batch overfit, finite gradients, and checkpoint resume. Train under a fixed token budget and evaluate held-out loss/perplexity plus generation probes. Do not advance merely because loss fell: require artifact reload, no split leakage, acceptable tokenizer behavior, and documented data lineage."),
        ("49.3 Instruction tuning gate", "Construct a small, licensed instruction dataset with exact chat template and assistant-only loss mask. Evaluate the base checkpoint first. Apply full or LoRA SFT, recording trainable parameters, effective tokens, schedule, and checkpoints. Compare base and tuned models on instruction following, output format, retention, and safety cases. A toy pretrained model may lack capacity and knowledge; negative results are expected and should be explained rather than hidden."),
        ("49.4 Release and reflection", "Package weights, configuration, tokenizer, template, generation defaults, provenance, evaluation report, and model card. Reload in a clean process and compare fixed logits. Document intended use, limitations, license, compute, data, failures, and why the model is not production-ready. The final report traces every measured behavior to a build decision and proposes the highest-value next experiment under a fixed budget."),
    ], [
        'plan={"context":128,"vocab":512,"parameters":500_000,"train_tokens":100_000,"epochs":1}; print(plan)',
        'gates={"roundtrip":True,"no_leakage":True,"one_batch_overfit":True,"checkpoint_reload":True}; print("pretrain ready",all(gates.values()))',
        'comparison={"base_format":.1,"sft_format":.8,"base_loss":4.2,"sft_retention_loss":4.5}; print(comparison)',
        'release=["config","weights","tokenizer","chat_template","model_card","eval_report","manifest"]; print(release)'
    ], ["Complete the capstone with one epoch.", "Write a model card with negative results.", "Propose a compute-matched next experiment."])

    dense("09_capstones/50_capstone_grounded_assistant.ipynb", "Capstone II: Build and Evaluate a Grounded Assistant", ["Integrate model selection, prompting, hybrid RAG, tools, and structure", "Evaluate retrieval, answers, citations, security, and latency", "Serve the system locally with a reproducible contract"], [
        ("50.1 Requirements and baseline", "Define users, questions, authoritative sources, freshness, citation and abstention rules, latency, privacy, and threat boundaries. Select an open instruct model using measured constraints and pin its tokenizer/template. Build a no-retrieval prompt baseline on a frozen dataset containing answerable, unanswerable, identifier-heavy, conflicting, stale, and adversarial cases. This reveals what retrieval must improve and prevents complexity from receiving credit for model knowledge."),
        ("50.2 Retrieval and grounded generation", "Parse versioned documents, preserve metadata and access controls, chunk with source offsets, and build lexical plus dense indexes. Evaluate each retriever, reciprocal-rank fusion, reranking, and context diversity before generation. Assemble evidence under a token budget and treat it as untrusted data. Require source IDs and abstention. Validate that citations exist and support material claims; citation presence alone is not correctness."),
        ("50.3 Tools, security, and operations", "Add one narrow read-only tool only when retrieval cannot answer current or exact information. Validate arguments and keep authorization in the host. Test indirect prompt injection, unauthorized sources, oversized documents, stale caches, tool timeouts, and malformed structured output. Trace retrieval, reranking, generation, validation, and tools with redaction. Serve through Ollama or a compatible endpoint and test the exact template and API contract."),
        ("50.4 Evaluation and release", "Compare baseline, dense, hybrid, reranked, and tool-enabled variants. Report Recall@k, MRR, answer correctness, faithfulness, citation precision/recall, abstention, latency percentiles, tokens, and critical security failures by slice. Promote only if target gains justify complexity and no authorization violation occurs. Package index/data/model/prompt revisions, deployment config, system card, rollback plan, and deletion lineage."),
    ], [
        'requirements={"citations":True,"abstain":True,"p95_seconds":3,"private_sources":True}; print(requirements)',
        'variants=["prompt_only","dense","hybrid","hybrid_reranked","hybrid_plus_tool"]; print(variants)',
        'tests=["unanswerable","conflicting_sources","injection","unauthorized_document","tool_timeout","stale_cache"]; print(tests)',
        'metrics={"recall@5":.9,"answer_accuracy":.78,"citation_precision":.94,"critical_violations":0,"p95":2.4}; print("release",metrics["critical_violations"]==0 and metrics["p95"]<=3)'
    ], ["Build all five ablation variants.", "Validate claim-level citations.", "Produce a system card and rollback drill."])

    dense("09_capstones/51_capstone_operate_agent_system.ipynb", "Capstone III: Operate a Durable Multi-Agent System", ["Combine durable state, MCP tools, approvals, and specialist agents", "Evaluate trajectories, failure recovery, security, and capacity", "Produce an operational release with rollback and governance"], [
        ("51.1 Workflow architecture", "Choose a consequential but sandboxable task and first implement a deterministic workflow. Add one agent only for ambiguous decisions, then justify any specialist agents through context or permission isolation. Define typed state, events, task envelopes, tool schemas, terminal states, global budgets, and owners. Use MCP for composable capabilities without treating discovered servers as trusted. Draw every identity, data, and side-effect boundary before executing."),
        ("51.2 Durability and multi-agent coordination", "Checkpoint before and after effects, issue stable idempotency keys, retain receipts, propagate cancellation, and resume after injected crashes. Human approval binds to an immutable proposed action and expires. A supervisor may route only registered roles; specialists receive least context and tools; parallel results merge deterministically with dissent preserved. Shared state is authoritative only through validated transitions, not agent-authored prose."),
        ("51.3 Evaluation and adversarial testing", "Create a deterministic environment and frozen tasks. Compare deterministic, single-agent, and multi-agent variants under equal model, permission, token, tool-call, and time budgets. Score task success, tool choice and arguments, effects, duplicated work, conflicts, intervention, steps, tokens, latency, and critical violations. Inject malformed calls, poisoned MCP resources, revoked permissions, duplicate delivery, worker loss, stale approval, sandbox attacks, and malicious specialists."),
        ("51.4 Deployment and governance", "Serve the pinned model through vLLM or the selected engine behind authenticated ingress and admission control. Trace state transitions and effects without retaining sensitive payloads unnecessarily. Canary with read-only scopes, rehearse rollback, and publish a system card containing versions, architecture, threat model, evaluations, known limitations, monitoring, ownership, and incident response. Conclude with an ablation-based answer to whether multiple agents improved the workflow enough to remain."),
    ], [
        'architecture={"host":"policy + durable state","servers":["catalog","sandbox"],"agents":["supervisor","researcher","reviewer"],"human_gate":"external writes"}; print(architecture)',
        'states=["ready","planning","running","waiting_approval","committing","done","failed","cancelled"]; print(states)',
        'faults=["crash_before_effect","crash_after_effect","malicious_resource","revoked_scope","worker_timeout","duplicate_message"]; print(faults)',
        'comparison={"deterministic":.62,"single_agent":.81,"multi_agent":.84,"multi_agent_cost_ratio":2.3}; print(comparison,"keep only if bounded gains justify cost")'
    ], ["Implement crash and resume tests.", "Run matched-budget architecture ablations.", "Publish a system card and incident drill."])
